window.AUTH=window.AUTH||{};window.AUTH["18-1269"]={"d":"18-1269","id":"2019/18-1269","n":"Rodriguez v. Federal Deposit Insurance Corp.","briefs":[{"k":"petitioner","label":"Brief of petitioner Simon E. Rodriguez, as Chapter 7 Trustee for the Bankruptcy Estate of United Western Bancorp, Inc.","date":"2019-08-30","url":"https://www.supremecourt.gov/DocketPDF/18/18-1269/114284/20190830130850437_18-1269%20ts.pdf","side":"pet","n":108},{"k":"respondent","label":"Brief of respondent Federal Deposit Insurance Corporation, as Receiver for United Western Bank","date":"2019-10-17","url":"https://www.supremecourt.gov/DocketPDF/18/18-1269/119409/20191017175203027_18-1269bsUnitedStates.pdf","side":"res","n":51},{"k":"reply","label":"Reply of petitioner Simon E. Rodriguez, as Chapter 7 Trustee for the Bankruptcy Estate of United Western Bancorp, Inc.","date":"2019-11-14","url":"https://www.supremecourt.gov/DocketPDF/18/18-1269/122396/20191114120838320_No.%2018-1269rb.pdf","side":"pet","n":18}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/589US1PP_Web.pdf#page=173","tr":true,"items":[{"t":"case","label":"Am. Elec. Power Co. v. Connecticut","cite":"564 U.S. 410","y":2011,"id":"2010/10-174","sc":1,"op":1,"sum":"The Court held that held the Clean Air Act bars suits by governmental bodies and private parties seeking to curb emissions from utilities via the federal common law.","sumSrc":"Oyez","by":{"0":"passim"}},{"t":"case","label":"Atherton v. FDIC","cite":"519 U.S. 213","y":1997,"id":"1996/95-928","sc":1,"sum":"The unanimous Court concluded that \"state law sets the standard of conduct as long as the state standard is stricter than that of the federal statute.\" The opinion by Justice Stephen Breyer held that the federal \"gross negligence\" statute was only intended to set a \"floor\" or minimum standard for state laws governing negligent conduct.","sumSrc":"Oyez","by":{"0":"passim","1":"36"}},{"t":"case","label":"Banco Nacional de Cuba v. Sabbatino","cite":"376 U.S. 398","y":1964,"id":"1963/16","sc":1,"op":1,"sum":"The Supreme Court held that it will not decide the validity of a decree by a foreign government absent a treaty or other agreement. It did not matter that the taking violated customary international law. The majority noted that a judicial decision on this issue without a treaty would strain U.S.-Cuba relations.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Bank of Am. Nat’l Trust & Sav. Ass’n v. Parnell","cite":"352 U.S. 29","y":1956,"id":"1956/21","sc":1,"sum":"The judgment of the Court of Appeals is reversed and the case is remanded to that Court for further proceedings.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20, 29"}},{"t":"case","label":"Barnes v. Harris","cite":"783 F.3d 1185","y":2015,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/783/1185/","ar":1,"by":{"0":"16, 17, 18, 36","1":"7, 13"}},{"t":"case","label":"BFP v. Resolution Trust Corp.","cite":"511 U.S. 531","y":1994,"id":"1993/92-1370","sc":1,"sum":"The Court ruled 5-4 that the value received for a property at a foreclosure sale can be reasonable even if it is different from the \"fair market value.\" A foreclosure sale alters market conditions and can lower a property's selling price.","sumSrc":"Oyez","by":{"0":"28","2":"14"}},{"t":"case","label":"Bob Jones Univ. v. United States","cite":"461 U.S. 574","y":1983,"id":"1982/81-3","sc":1,"sum":"The Court found that the IRS was correct in its decision to revoke the tax-exempt status of Bob Jones University and the Goldsboro Christian School. These institutions did not meet the requirement by providing \"beneficial and stabilizing influences in community life\" to be supported by taxpayers with a special tax status. The schools could not meet this requirement due to their discriminatory policies.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Boyle v. United Techs. Corp.","cite":"487 U.S. 500","y":1988,"id":"1987/86-492","sc":1,"sum":"In a 5-to4 decision, the Court held that despite the absence of specific legislation immunizing government contractors from liability for design flaws, questions of their liability are of unique federal concern. As such, to the extent that it holds military contractors liable for design flaws, state law may significantly conflict with federal interests thereby requiring its displacement.","sumSrc":"Oyez","by":{"0":"passim"}},{"t":"case","label":"Buchser v. Buchser","cite":"231 U.S. 157","y":1913,"id":"scdb/1913-046","sc":1,"sum":"Unless the statutes of the United States control, this court follows the state court as to whether real estate is separate or community property.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"Butner v. United States","cite":"440 U.S. 48","y":1979,"id":"1978/77-1410","sc":1,"op":1,"sum":"Apart from certain special provisions, the Bankruptcy Act generally leaves the determination of property rights in the assets of a bankrupt's estate to BUTNER v. UNITED STATES","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"Capital Bancshares, Inc. v. FDIC","cite":"957 F.2d 203","y":1992,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/957/203/","sum":"Holding that “an inconsistent practice” could not support “the existence of an implied agreement”.","sumSrc":"brief:0","by":{"0":"12, 35","1":"7","2":"8"}},{"t":"case","label":"City of Aurora ex rel. Util. Enter. v. Colo. State Eng’r","cite":"105 P.3d 595","y":2005,"court":"Colo.","url":"https://www.courtlistener.com/c/P.3d/105/595/","ar":1,"by":{"0":"23, 52","1":"41","2":"16"}},{"t":"case","label":"City of Milwaukee v. Illinois & Michigan","cite":"451 U.S. 304","y":1981,"id":"1980/79-408","sc":1,"sum":"In original proceedings brought by respondent State of Illinois, alleging that petitioners-the city of Milwaukee, its Sewerage Commission, and Milwaukee County's Metropolitan Sewerage Commission-and other Wisconsin cities were polluting Lake Michigan because of overflows of untreated sewage from their sewer systems and discharges of inadequately treated sewage from their treatment plants, this Court recognized the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim"}},{"t":"case","label":"Comm’r v. Lundy","cite":"516 U.S. 235","y":1996,"id":"1995/94-1785","sc":1,"sum":"The Court held that in these circumstances a 2-year look-back period applies and the Tax Court lacks jurisdiction to award a refund.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"County of Oneida v. Oneida Indian Nation of N.Y.","cite":"470 U.S. 226","y":1985,"id":"1984/83-1065","sc":1,"sum":"Respondent Indian Tribes (hereafter respondents) brought an action in Federal District Court against petitioner counties (hereafter petitioners), alleging that respondents' ancestors conveyed tribal land to New York State, under a 1795 agreement that violated the Nonintercourse Act of 1793-which provided that no person or entity could purchase Indian land without the Federal Government's approval-and that thus the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"Erie Railroad Co. v. Tompkins","cite":"304 U.S. 64","y":1938,"id":"1900-1940/304us64","sc":1,"op":1,"sum":"A case in which the Court overturned its prior decision in Swift v. Tyson and held that federal courts exercising diversity jurisdiction cannot create their own common law for issues that properly fall within state law.","sumSrc":"Oyez","by":{"0":"19, 24"}},{"t":"case","label":"FDIC v. AmFin Fin. Corp.","cite":"757 F.3d 530","y":2014,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/757/530/","op":2,"by":{"0":"11, 12, 16, 35","1":"7"}},{"t":"case","label":"FDIC v. FBOP Corp.","cite":"252 F. Supp. 3d 664","y":2017,"court":"N.D. Ill.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/252/664/","by":{"0":"11","1":"30"}},{"t":"case","label":"Hinderlider v. La Plata River & Cherry Creek Ditch Co.","cite":"304 U.S. 92","y":1938,"id":"scdb/1937-042","sc":1,"op":1,"sum":"1. The water of an interstate stream, used beneficially in each of the two States through which it flows, must be equitably apportioned between the two. P. 101. The claim that on interstate streams the upper State has such ownership or control of the whole stream as entitles it to divert all the.water, regardless of any injury or prejudice to the lower State, has been consistently denied by this Court. P. 102.--'. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"Interlake Corp. v. Comm’r","cite":"112 T.C. 103","y":1999,"url":"https://www.courtlistener.com/c/T.C./112/103/","sum":"Stating that the regulations make the parent “the exclusive agent for the consolidated group with respect to all procedural matters.”.","sumSrc":"brief:0","by":{"0":"42"}},{"t":"case","label":"Kamen v. Kemper Fin. Servs., Inc.","cite":"500 U.S. 90","y":1991,"id":"1990/90-516","sc":1,"sum":"A court entertaining a derivative action under the ICA must apply the demand futility exception as it is defined by the law of the State of incorporation.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim"}},{"t":"case","label":"Miree v. DeKalb County","cite":"433 U.S. 25","y":1977,"id":"1976/76-607","sc":1,"sum":"1. In petitioners' consolidated diversity actions against respondent county arising out of an aircraft crash at the county's airport, state rather than federal law held to apply to the resolution of petitioners' claim that, as, respectively, survivors of deceased passengers, the assignee of the aircraft owner, and a burn victim, they are the third-party beneficiaries of grant contracts between the county and the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"Mobil Oil Corp. v. Higginbotham","cite":"436 U.S. 618","y":1978,"id":"1977/76-1726","sc":1,"sum":"In an action for wrongful death on the high seas, the measure of damages is governed by the Death on the High Seas Act, 46 U. S. C. § 762, which limits a decedent's survivors' recovery to their \"pecuniary loss,\" and hence the survivors are not entitled to recover additional damages under general maritime law for \"loss of society.\" Pp. 620-626. 545 F. 2d 422, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26, 30, 31, 41"}},{"t":"case","label":"Montano v. Land Title Guarantee Co.","cite":"778 P.2d 328","y":1989,"court":"Colo. App.","url":"https://www.courtlistener.com/c/P.2d/778/328/","by":{"0":"52","2":"18"}},{"t":"case","label":"Norfolk S. Ry. Co. v. Kirby","cite":"543 U.S. 14","y":2004,"id":"2004/02-1028","sc":1,"op":1,"sum":"The Court held that federal law controlled the interpretation of both bills, because they were maritime contracts and the dispute was not inherently local. The Court also held that the 11th Circuit misinterpreted the bills as not protecting Norfolk.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Nw. Airlines, Inc. v. Transp. Workers Union","cite":"451 U.S. 77","y":1981,"id":"1980/79-1056","sc":1,"sum":"Petitioner has neither a federal statutory nor a federal common-law right to contribution from respondent unions.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"O’Melveny & Myers v. FDIC","cite":"512 U.S. 79","y":1994,"id":"1993/93-489","sc":1,"sum":"Respondent Federal Deposit Insurance Corporation (FDIC), receiver for an insolvent California savings and loan (S&L), caused the S&L to make refunds to investors in certain fraudulent real estate syndications in which the S&L had been represented by petitioner law firm. The FDIC filed suit against petitioner in the Federal District Court and alleged state causes of action for professional negligence and breach of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim"}},{"t":"case","label":"Old Mission Portland Cement Co. v. Helvering","cite":"293 U.S. 289","y":1934,"id":"scdb/1934-029","sc":1,"sum":"1. In consolidated income tax returns made by two affiliated corporations under § 240 of the Revenue Acts of 1921, 1924 and 1926, and supplementary Treasury Regulations, there cannot be deductions of amortized discount on bonds which were issued by one ot the affiliates and were purchased and are held by the other, since the anticipated payment of the face of the bonds at maturity, which. alone gives occasion fur …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"1, 5, 50"}},{"t":"case","label":"Pilot Life Ins. Co. v. Dedeaux","cite":"481 U.S. 41","y":1987,"id":"1986/85-1043","sc":1,"sum":"ERISA pre-empts respondent's suit under state common law for alleged improper processing of his claim for benefits under the ERISAregulated benefit plan.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"S. Pac. Co. v. Comm’r","cite":"84 T.C. 395","y":1985,"url":"https://www.courtlistener.com/c/T.C./84/395/","by":{"0":"42"}},{"t":"case","label":"Segal v. Rochelle","cite":"382 U.S. 375","y":1966,"id":"1965/44","sc":1,"sum":"On September 27, 1961, the individual petitioners and their business partnership filed bankruptcy petitions. After the end of that year loss-carryback federal income tax refunds were obtained for the individual petitioners based on the firm's losses during 1961 prior to bankruptcy which were offset against income for 1959.and 1960 on which taxes had been paid. These refunds, on deposit in a special account by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10"}},{"t":"case","label":"Semtek Int’l Inc. v. Lockheed Martin Corp.","cite":"531 U.S. 497","y":2001,"id":"2000/99-1551","sc":1,"sum":"The Court held that \"[b]ecause the claim-preclusive effect of a federal court's dismissal 'upon the merits' of a diversity action on state statute-of-limitations grounds is governed by a federal rule, which in turn (in diversity cases) incorporates the claim-preclusion law that would be applied by state courts in the State in which the federal court sits, the Maryland Court of Special Appeals erred in holding that the California federal court's dismissal 'upon the merits' necessarily precluded the Maryland state-court action.\" Thus, the District Court's dismissal on the merits of claims as untimely under California law did not preclude Semtek from asserting its claims in a different state court forum.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Sosa v. Alvarez-Machain","cite":"542 U.S. 692","y":2004,"id":"2003/03-339","sc":1,"op":1,"sum":"No and No. On the Alien Tort Statute claim, the Court unanimously ruled that the ATS did not create a separate ground of suit for violations of the law of nations. Instead, it was intended only to give courts jurisdiction over traditional law of nations cases - those involving ambassadors, for example, or piracy.","sumSrc":"Oyez","by":{"0":"19, 25"}},{"t":"case","label":"Stern v. Marshall","cite":"564 U.S. 462","y":2011,"id":"2010/10-179","sc":1,"sum":"The Court held that the Bankruptcy Court did not have the constitutional authority to enter judgement on the petitioner's counterclaim.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Stortroen v. Beneficial Fin. Co. of Colo.","cite":"736 P.2d 391","y":1987,"court":"Colo.","url":"https://www.courtlistener.com/c/P.2d/736/391/","by":{"0":"23, 52, 55","1":"41, 44"}},{"t":"case","label":"Texas Indus., Inc. v. Radcliff Materials, Inc.","cite":"451 U.S. 630","y":1981,"id":"1980/79-1144","sc":1,"op":1,"sum":"There is no basis in federal statutory or common law for allowing federal courts to fashion the right to contribution urged by petitioner.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25, 27"}},{"t":"case","label":"Textile Workers v. Lincoln Mills","cite":"353 U.S. 448","y":1957,"id":"1956/211","sc":1,"sum":"A union entered into a collective-bargaining agreement with an employer providing that there would be no strikes or work stoppages and that grievances would be handled pursuant to a specified procedure, the last step of which was arbitration. Grievances arose and were processed through various steps in the grievance procedure until the union's demands were finally denied by the employer. The union requested …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"United Dominion Indus., Inc. v. United States","cite":"532 U.S. 822","y":2001,"id":"2000/00-157","sc":1,"sum":"The Court held that an affiliated group's product liability loss must be figured on a consolidated, single-entity basis, and not by aggregating product liability losses separately determined company by company.","sumSrc":"Oyez","by":{"0":"passim","1":"30","2":"9"}},{"t":"case","label":"United States v. Kimbell Foods, Inc.","cite":"440 U.S. 715","y":1979,"id":"1978/77-1359","sc":1,"sum":"These cases present the question whether contractual liens arising from certain federal loan programs take precedence over private liens, absent a federal statute that sets priorities. Resolution of this question requires determination of whether federal or state law governs the conflicting claims and, if federal law applies, whether a uniform priority rule should be fashioned or state commercial law should be …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35, 36, 40"}},{"t":"case","label":"United States v. Nat’l Bank of Commerce","cite":"472 U.S. 713","y":1985,"id":"1984/84-498","sc":1,"op":1,"sum":"The IRS had a right to levy on the joint accounts in question.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"United States v. Yazell","cite":"382 U.S. 341","y":1966,"id":"1965/10","sc":1,"sum":"Texas law. In a 6-3 decision, Justice Abe Fortas wrote for the majority holding that there was no overwhelming federal interest. The Government had voluntarily negotiated the contract knowing of the references to Texas law. The Court also noted there was no federal law, regulation, or contractual provision that allowed for application of federal law in this case.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Wallis v. Pan Am. Petroleum Corp.","cite":"384 U.S. 63","y":1966,"id":"1965/341","sc":1,"sum":"State law, which generally controls the dealings of private parties in an oil and gas lease validly issued under the Mineral Leasing Act of 1920, governs the controversy in this case.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim"}},{"t":"case","label":"Wheeldin v. Wheeler","cite":"373 U.S. 647","y":1963,"id":"1962/493","sc":1,"sum":"Basing jurisdiction on 28 U. S. C. § 1331 and not alleging diversity of citizenship, petitioner Dawson brought suit in a Federal District Court against respondent, an investigator for the House Committee on Un-American Activities. Petitioner alleged that, without authorization from the Committee but acting under color of his office, respondent had caused a subpoena to appear as a witness before the Committee to be …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"usc","label":"11 U.S.C. § 541","url":"https://www.law.cornell.edu/uscode/text/11/541","subs":["(a)(1)","(d)"],"stext":{"head":"§541. Property of the estate","paras":[[0,"(a) The commencement of a case under section 301, 302, or 303 of this title creates an estate. Such estate is comprised of all the following property, wherever located and by whomever held:"],[1,"(1) Except as provided in subsections (b) and (c)(2) of this section, all legal or equitable interests of the debtor in property as of the commencement of the case."],[1,"(2) All interests of the debtor and the debtor's spouse in community property as of the commencement of the case that is—"],[2,"(A) under the sole, equal, or joint management and control of the debtor; or"],[2,"(B) liable for an allowable claim against the debtor, or for both an allowable claim against the debtor and an allowable claim against the debtor's spouse, to the extent that such interest is so liable."],[1,"(3) Any interest in property that the trustee recovers under section 329(b), 363(n), 543, 550, 553, or 723 of this title."],[1,"(4) Any interest in property preserved for the benefit of or ordered transferred to the estate under section 510(c) or 551 of this title."],[1,"(5) Any interest in property that would have been property of the estate if such interest had been an interest of the debtor on the date of the filing of the petition, and that the debtor acquires or becomes entitled to acquire within 180 days after such date—"],[2,"(A) by bequest, devise, or inheritance;"],[2,"(B) as a result of a property settlement agreement with the debtor's spouse, or of an interlocutory or final divorce decree; or"],[2,"(C) as a beneficiary of a life insurance policy or of a death benefit plan."],[1,"(6) Proceeds, product, offspring, rents, or profits of or from property of the estate, except such as are earnings from services performed by an individual debtor after the commencement of the case."],[1,"(7) Any interest in property that the estate acquires after the commencement of the case."],[0,"(b) Property of the estate does not include—"],[1,"(1) any power that the debtor may exercise solely for the benefit of an entity other than the debtor;"],[1,"(2) any interest of the debtor as a lessee under a lease of nonresidential real property that has terminated at the expiration of the stated term of such lease before the commencement of the case under this title, and ceases to include any interest of the debtor as a lessee under a lease of nonresidential real property that has terminated at the expiration of the stated term of such lease during the case;"],[1,"(3) any eligibility of the debtor to participate in programs authorized under the Higher Education Act of 1965 (20 U.S.C. 1001 et seq.; 42 U.S.C. 2751 et seq.),1 or any accreditation status or State licensure of the debtor as an educational institution;"],[1,"(4) any interest of the debtor in liquid or gaseous hydrocarbons to the extent that—"],[2,"(A)(i) the debtor has transferred or has agreed to transfer such interest pursuant to a farmout agreement or any written agreement directly related to a farmout agreement; and"],[2,"(ii) but for the operation of this paragraph, the estate could include the interest referred to in clause (i) only by virtue of section 365 or 544(a)(3) of this title; or"],[2,"(B)(i) the debtor has transferred such interest pursuant to a written conveyance of a production payment to an entity that does not participate in the operation of the property from which such production payment is transferred; and"],[2,"(ii) but for the operation of this paragraph, the estate could include the interest referred to in clause (i) only by virtue of section 365 or 542 of this title;"],[1,"(5) funds placed in an education individual retirement account (as defined in section 530(b)(1) of the Internal Revenue Code of 1986) not later than 365 days before the date of the filing of the petition in a case under this title, but—"],[2,"(A) only if the designated beneficiary of such account was a child, stepchild, grandchild, or stepgrandchild of the debtor for the taxable year for which funds were placed in such account;"],[2,"(B) only to the extent that such funds—"],[3,"(i) are not pledged or promised to any entity in connection with any extension of credit; and"],[3,"(ii) are not excess contributions (as described in section 4973(e) of the Internal Revenue Code of 1986); and"],[2,"(C) in the case of funds placed in all such accounts having the same designated beneficiary not earlier than 720 days nor later than 365 days before such date, only so much of such funds as does not exceed $5,000; 2"],[1,"(6) funds used to purchase a tuition credit or certificate or contributed to an account in accordance with section 529(b)(1)(A) of the Internal Revenue Code of 1986 under a qualified State tuition program (as defined in section 529(b)(1) of such Code) not later than 365 days before the date of the filing of the petition in a case under this title, but—"],[2,"(A) only if the designated beneficiary of the amounts paid or contributed to such tuition program was a child, stepchild, grandchild, or stepgrandchild of the debtor for the taxable year for which funds were paid or contributed;"],[2,"(B) with respect to the aggregate amount paid or contributed to such program having the same designated beneficiary, only so much of such amount as does not exceed the total contributions permitted under section 529(b)(6) of such Code with respect to such beneficiary, as adjusted beginning on the date of the filing of the petition in a case under this title by the annual increase or decrease (rounded to the nearest tenth of 1 percent) in the education expenditure category of the Consumer Price Index prepared by the Department of Labor; and"],[2,"(C) in the case of funds paid or contributed to such program having the same designated beneficiary not earlier than 720 days nor later than 365 days before such date, only so much of such funds as does not exceed $5,000; 2"],[1,"(7) any amount—"],[2,"(A) withheld by an employer from the wages of employees for payment as contributions—"],[3,"(i) to—"],[4,"(I) an employee benefit plan that is subject to title I of the Employee Retirement Income Security Act of 1974 or under an employee benefit plan which is a governmental plan under section 414(d) of the Internal Revenue Code of 1986;"],[4,"(II) a deferred compensation plan under section 457 of the Internal Revenue Code of 1986; or"],[4,"(III) a tax-deferred annuity under section 403(b) of the Internal Revenue Code of 1986;"],[0,"except that such amount under this subparagraph shall not constitute disposable income as defined in section 1325(b)(2); or"],[3,"(ii) to a health insurance plan regulated by State law whether or not subject to such title; or"],[2,"(B) received by an employer from employees for payment as contributions—"],[3,"(i) to—"],[4,"(I) an employee benefit plan that is subject to title I of the Employee Retirement Income Security Act of 1974 or under an employee benefit plan which is a governmental plan under section 414(d) of the Internal Revenue Code of 1986;"],[4,"(II) a deferred compensation plan under section 457 of the Internal Revenue Code of 1986; or"],[4,"(III) a tax-deferred annuity under section 403(b) of the Internal Revenue Code of 1986;"],[0,"except that such amount under this subparagraph shall not constitute disposable income, as defined in section 1325(b)(2); or"],[3,"(ii) to a health insurance plan regulated by State law whether or not subject to such title;"],[1,"(8) subject to subchapter III of chapter 5, any interest of the debtor in property where the debtor pledged or sold tangible personal property (other than securities or written or printed evidences of indebtedness or title) as collateral for a loan or advance of money given by a person licensed under law to make such loans or advances, where—"],[2,"(A) the tangible personal property is in the possession of the pledgee or transferee;"],[2,"(B) the debtor has no obligation to repay the money, redeem the collateral, or buy back the property at a stipulated price; and"],[2,"(C) neither the debtor nor the trustee have exercised any right to redeem provided under the contract or State law, in a timely manner as provided under State law and section 108(b);"],[1,"(9) any interest in cash or cash equivalents that constitute proceeds of a sale by the debtor of a money order that is made—"],[2,"(A) on or after the date that is 14 days prior to the date on which the petition is filed; and"],[2,"(B) under an agreement with a money order issuer that prohibits the commingling of such proceeds with property of the debtor (notwithstanding that, contrary to the agreement, the proceeds may have been commingled with property of the debtor),"],[1,"unless the money order issuer had not taken action, prior to the filing of the petition, to require compliance with the prohibition; or"],[1,"(10) funds placed in an account of a qualified ABLE program (as defined in section 529A(b) of the Internal Revenue Code of 1986) not later than 365 days before the date of the filing of the petition in a case under this title, but—"],[2,"(A) only if the designated beneficiary of such account was a child, stepchild, grandchild, or stepgrandchild of the debtor for the taxable year for which funds were placed in such account;"],[2,"(B) only to the extent that such funds—"],[3,"(i) are not pledged or promised to any entity in connection with any extension of credit; and"],[3,"(ii) are not excess contributions (as described in section 4973(h) of the Internal Revenue Code of 1986); and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/541?type=usc&year=mostrecent&link-type=html"},"head":"§541. Property of the estate","tname":"Bankruptcy","by":{"0":"10, 10, 52","1":"2, 12, 2, 12"}},{"t":"usc","label":"12 U.S.C. § 371c","url":"https://www.law.cornell.edu/uscode/text/12/371c","subs":["(c)(1)","(c)(1)(a)"],"by":{"0":"38, 39"}},{"t":"usc","label":"12 U.S.C. § 371c-1","url":"https://www.law.cornell.edu/uscode/text/12/371c-1","subs":["(a)(1)","(a)(1)(A)"],"by":{"0":"39, 38"}},{"t":"usc","label":"12 U.S.C. § 1821","url":"https://www.law.cornell.edu/uscode/text/12/1821","subs":["(d)(2)(A)(i)"],"stext":{"head":"§1821. Insurance Funds","paras":[[0,"(a) Deposit insurance"],[0,"(1) Insured amounts payable"],[0,"(A) In general"],[2,"The Corporation shall insure the deposits of all insured depository institutions as provided in this chapter."],[0,"(B) Net amount of insured deposit"],[2,"The net amount due to any depositor at an insured depository institution shall not exceed the standard maximum deposit insurance amount as determined in accordance with subparagraphs (C), (D), (E) and (F) and paragraph (3)."],[0,"(C) Aggregation of deposits"],[2,"For the purpose of determining the net amount due to any depositor under subparagraph (B), the Corporation shall aggregate the amounts of all deposits in the insured depository institution which are maintained by a depositor in the same capacity and the same right for the benefit of the depositor either in the name of the depositor or in the name of any other person, other than any amount in a trust fund described in paragraph (1) or (2) of section 1817(i) of this title or any funds described in section 1817(i)(3) of this title."],[0,"(D) Coverage for certain employee benefit plan deposits"],[0,"(i) Pass-through insurance"],[3,"The Corporation shall provide pass-through deposit insurance for the deposits of any employee benefit plan."],[0,"(ii) Prohibition on acceptance of benefit plan deposits"],[3,"An insured depository institution that is not well capitalized or adequately capitalized may not accept employee benefit plan deposits."],[0,"(iii) Definitions"],[3,"For purposes of this subparagraph, the following definitions shall apply:"],[0,"(I) Capital standards"],[4,"The terms \"well capitalized\" and \"adequately capitalized\" have the same meanings as in section 1831o of this title."],[0,"(II) Employee benefit plan"],[4,"The term \"employee benefit plan\" has the same meaning as in paragraph (5)(B)(ii), and includes any eligible deferred compensation plan described in section 457 of title 26."],[0,"(III) Pass-through deposit insurance"],[4,"The term \"pass-through deposit insurance\" means, with respect to an employee benefit plan, deposit insurance coverage based on the interest of each participant, in accordance with regulations issued by the Corporation."],[0,"(E) Standard maximum deposit insurance amount defined"],[2,"For purposes of this chapter, the term \"standard maximum deposit insurance amount\" means $250,000, adjusted as provided under subparagraph (F) after March 31, 2010. Notwithstanding any other provision of law, the increase in the standard maximum deposit insurance amount to $250,000 shall apply to depositors in any institution for which the Corporation was appointed as receiver or conservator on or after January 1, 2008, and before October 3, 2008. The Corporation shall take such actions as are necessary to carry out the requirements of this section with respect to such depositors, without regard to any time limitations under this chapter. In implementing this and the preceding 2 sentences, any payment on a deposit claim made by the Corporation as receiver or conservator to a depositor above the standard maximum deposit insurance amount in effect at the time of the appointment of the Corporation as receiver or conservator shall be deemed to be part of the net amount due to the depositor under subparagraph (B)."],[0,"(F) Inflation adjustment"],[0,"(i) In general"],[3,"By April 1 of 2010, and the 1st day of each subsequent 5-year period, the Board of Directors and the National Credit Union Administration Board shall jointly consider the factors set forth under clause (v), and, upon determining that an inflation adjustment is appropriate, shall jointly prescribe the amount by which the standard maximum deposit insurance amount and the standard maximum share insurance amount (as defined in section 1787(k) of this title) applicable to any depositor at an insured depository institution shall be increased by calculating the product of—"],[4,"(I) $100,000; and"],[4,"(II) the ratio of the published annual value of the Personal Consumption Expenditures Chain-Type Price Index (or any successor index thereto), published by the Department of Commerce, for the calendar year preceding the year in which the adjustment is calculated under this clause, to the published annual value of such index for the calendar year preceding April 1, 2006."],[0,"The values used in the calculation under subclause (II) shall be, as of the date of the calculation, the values most recently published by the Department of Commerce."],[0,"(ii) Rounding"],[3,"If the amount determined under clause (ii) for any period is not a multiple of $10,000, the amount so determined shall be rounded down to the nearest $10,000."],[0,"(iii) Publication and report to the Congress"],[3,"Not later than April 5 of any calendar year in which an adjustment is required to be calculated under clause (i) to the standard maximum deposit insurance amount and the standard maximum share insurance amount under such clause, the Board of Directors and the National Credit Union Administration Board shall—"],[4,"(I) publish in the Federal Register the standard maximum deposit insurance amount, the standard maximum share insurance amount, and the amount of coverage under paragraph (3)(A) and section 1787(k)(3) of this title, as so calculated; and"],[4,"(II) jointly submit a report to the Congress containing the amounts described in subclause (I)."],[0,"(iv) 6-month implementation period"],[3,"Unless an Act of Congress enacted before July 1 of the calendar year in which an adjustment is required to be calculated under clause (i) provides otherwise, the increase in the standard maximum deposit insurance amount and the standard maximum share insurance amount shall take effect on January 1 of the year immediately succeeding such calendar year."],[0,"(v) Inflation adjustment consideration"],[3,"In making any determination under clause (i) to increase the standard maximum deposit insurance amount and the standard maximum share insurance amount, the Board of Directors and the National Credit Union Administration Board shall jointly consider—"],[4,"(I) the overall state of the Deposit Insurance Fund and the economic conditions affecting insured depository institutions;"],[4,"(II) potential problems affecting insured depository institutions; or"],[4,"(III) whether the increase will cause the reserve ratio of the fund to fall below 1.15 percent of estimated insured deposits."],[0,"(2) Government depositors"],[0,"(A) In general"],[2,"Notwithstanding any limitation in this chapter or in any other provision of law relating to the amount of deposit insurance available to any 1 depositor—"],[3,"(i) a government depositor shall, for the purpose of determining the amount of insured deposits under this subsection, be deemed to be a depositor separate and distinct from any other officer, employee, or agent of the United States or any public unit referred to in subparagraph (B); and"],[3,"(ii) except as provided in subparagraph (C), the deposits of a government depositor shall be insured in an amount equal to the standard maximum deposit insurance amount (as determined under paragraph (1))."],[0,"(B) Government depositor"],[2,"In this paragraph, the term \"government depositor\" means a depositor that is—"],[3,"(i) an officer, employee, or agent of the United States having official custody of public funds and lawfully investing or depositing the same in time and savings deposits in an insured depository institution;"],[3,"(ii) an officer, employee, or agent of any State of the United States, or of any county, municipality, or political subdivision thereof having official custody of public funds and lawfully investing or depositing the same in time and savings deposits in an insured depository institution in such State;"],[3,"(iii) an officer, employee, or agent of the District of Columbia having official custody of public funds and lawfully investing or depositing the same in time and savings deposits in an insured depository institution in the District of Columbia;"],[3,"(iv) an officer, employee, or agent of the Commonwealth of Puerto Rico, of the Virgin Islands, of American Samoa, of the Trust Territory of the Pacific Islands, or of Guam, or of any county, municipality, or political subdivision thereof having official custody of public funds and lawfully investing or depositing the same in time and savings deposits in an insured depository institution in the Commonwealth of Puerto Rico, the Virgin Islands, American Samoa, the Trust Territory of the Pacific Islands, or Guam, respectively; or"],[3,"(v) an officer, employee, or agent of any Indian tribe (as defined in section 1452(c) of title 25) or agency thereof having official custody of tribal funds and lawfully investing or depositing the same in time and savings deposits in an insured depository institution."],[0,"(C) Authority to limit deposits"],[2,"The Corporation may limit the aggregate amount of funds that may be invested or deposited in deposits in any insured depository institution by any government depositor on the basis of the size of any such bank 1 in terms of its assets: Provided, however, such limitation may be exceeded by the pledging of acceptable securities to the government depositor when and where required."],[0,"(3) Certain retirement accounts"],[0,"(A) In general"],[2,"Notwithstanding any limitation in this chapter relating to the amount of deposit insurance available for the account of any 1 depositor, deposits in an insured depository institution made in connection with—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/1821?type=usc&year=mostrecent&link-type=html"},"head":"§1821. Insurance Funds","tname":"Banks and Banking","by":{"0":"30","1":"12, 12"}},{"t":"usc","label":"26 U.S.C. § 172","url":"https://www.law.cornell.edu/uscode/text/26/172","subs":["(b)(1)(A)","(c)"],"by":{"0":"42, 42"}},{"t":"usc","label":"26 U.S.C. § 1501","url":"https://www.law.cornell.edu/uscode/text/26/1501","stext":{"head":"§1501. Privilege to file consolidated returns","paras":[[0,"An affiliated group of corporations shall, subject to the provisions of this chapter, have the privilege of making a consolidated return with respect to the income tax imposed by chapter 1 for the taxable year in lieu of separate returns. The making of a consolidated return shall be upon the condition that all corporations which at any time during the taxable year have been members of the affiliated group consent to all the consolidated return regulations prescribed under section 1502 prior to the last day prescribed by law for the filing of such return. The making of a consolidated return shall be considered as such consent. In the case of a corporation which is a member of the affiliated group for a fractional part of the year, the consolidated return shall include the income of such corporation for such part of the year as it is a member of the affiliated group."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/1501?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1501. Privilege to file consolidated returns","tname":"Internal Revenue Code","by":{"0":"32, 1, 4","1":"2"}},{"t":"usc","label":"26 U.S.C. § 1502","url":"https://www.law.cornell.edu/uscode/text/26/1502","stext":{"head":"§1502. Regulations","paras":[[0,"The Secretary shall prescribe such regulations as he may deem necessary in order that the tax liability of any affiliated group of corporations making a consolidated return and of each corporation in the group, both during and after the period of affiliation, may be returned, determined, computed, assessed, collected, and adjusted, in such manner as clearly to reflect the income-tax liability and the various factors necessary for the determination of such liability, and in order to prevent avoidance of such tax liability. In carrying out the preceding sentence, the Secretary may prescribe rules that are different from the provisions of chapter 1 that would apply if such corporations filed separate returns."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/1502?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1502. Regulations","tname":"Internal Revenue Code","by":{"0":"5, 20, 32","1":"2"}},{"t":"usc","label":"26 U.S.C. § 1504","url":"https://www.law.cornell.edu/uscode/text/26/1504","subs":["(a)","(a)(1)","(a)(2)"],"stext":{"head":"§1504. Definitions","paras":[[0,"(a) Affiliated group defined"],[0,"For purposes of this subtitle—"],[0,"(1) In general"],[1,"The term \"affiliated group\" means—"],[2,"(A) 1 or more chains of includible corporations connected through stock ownership with a common parent corporation which is an includible corporation, but only if—"],[2,"(B)(i) the common parent owns directly stock meeting the requirements of paragraph (2) in at least 1 of the other includible corporations, and"],[2,"(ii) stock meeting the requirements of paragraph (2) in each of the includible corporations (except the common parent) is owned directly by 1 or more of the other includible corporations."],[0,"(2) 80-percent voting and value test"],[1,"The ownership of stock of any corporation meets the requirements of this paragraph if it—"],[2,"(A) possesses at least 80 percent of the total voting power of the stock of such corporation, and"],[2,"(B) has a value equal to at least 80 percent of the total value of the stock of such corporation."],[0,"(3) 5 years must elapse before reconsolidation"],[0,"(A) In general"],[2,"If—"],[3,"(i) a corporation is included (or required to be included) in a consolidated return filed by an affiliated group, and"],[3,"(ii) such corporation ceases to be a member of such group,"],[2,"with respect to periods after such cessation, such corporation (and any successor of such corporation) may not be included in any consolidated return filed by the affiliated group (or by another affiliated group with the same common parent or a successor of such common parent) before the 61st month beginning after its first taxable year in which it ceased to be a member of such affiliated group."],[0,"(B) Secretary may waive application of subparagraph (A)"],[2,"The Secretary may waive the application of subparagraph (A) to any corporation for any period subject to such conditions as the Secretary may prescribe."],[0,"(4) Stock not to include certain preferred stock"],[1,"For purposes of this subsection, the term \"stock\" does not include any stock which—"],[2,"(A) is not entitled to vote,"],[2,"(B) is limited and preferred as to dividends and does not participate in corporate growth to any significant extent,"],[2,"(C) has redemption and liquidation rights which do not exceed the issue price of such stock (except for a reasonable redemption or liquidation premium), and"],[2,"(D) is not convertible into another class of stock."],[0,"(5) Regulations"],[1,"The Secretary shall prescribe such regulations as may be necessary or appropriate to carry out the purposes of this subsection, including (but not limited to) regulations—"],[2,"(A) which treat warrants, obligations convertible into stock, and other similar interests as stock, and stock as not stock,"],[2,"(B) which treat options to acquire or sell stock as having been exercised,"],[2,"(C) which provide that the requirements of paragraph (2)(B) shall be treated as met if the affiliated group, in reliance on a good faith determination of value, treated such requirements as met,"],[2,"(D) which disregard an inadvertent ceasing to meet the requirements of paragraph (2)(B) by reason of changes in relative values of different classes of stock,"],[2,"(E) which provide that transfers of stock within the group shall not be taken into account in determining whether a corporation ceases to be a member of an affiliated group, and"],[2,"(F) which disregard changes in voting power to the extent such changes are disproportionate to related changes in value."],[0,"(b) Definition of \"includible corporation\""],[0,"As used in this chapter, the term \"includible corporation\" means any corporation except—"],[1,"(1) Corporations exempt from taxation under section 501."],[1,"(2) Insurance companies subject to taxation under section 801."],[1,"(3) Foreign corporations."],[1,"(4) Regulated investment companies and real estate investment trusts subject to tax under subchapter M of chapter 1."],[1,"(5) A DISC (as defined in section 992(a)(1))."],[1,"(6) An S corporation."],[0,"(c) Includible insurance companies"],[0,"Notwithstanding the provisions of paragraph (2) of subsection (b)—"],[1,"(1) Two or more domestic insurance companies each of which is subject to tax under section 801 shall be treated as includible corporations for purposes of applying subsection (a) to such insurance companies alone."],[1,"(2)(A) If an affiliated group (determined without regard to subsection (b)(2)) includes one or more domestic insurance companies taxed under section 801, the common parent of such group may elect (pursuant to regulations prescribed by the Secretary) to treat all such companies as includible corporations for purposes of applying subsection (a) except that no such company shall be so treated until it has been a member of the affiliated group for the 5 taxable years immediately preceding the taxable year for which the consolidated return is filed."],[1,"(B) If an election under this paragraph is in effect for a taxable year—"],[2,"(i) section 243(b)(3) and the exception provided under section 243(b)(2) with respect to subsections (b)(2) and (c) of this section,"],[2,"(ii) section 542(b)(5), and"],[2,"(iii) subsection (a)(4) and (b)(2)(D) of section 1563, and the reference to section 1563(b)(2)(D) contained in section 1563(b)(3)(C),"],[1,"shall not be effective for such taxable year."],[0,"(d) Subsidiary formed to comply with foreign law"],[0,"In the case of a domestic corporation owning or controlling, directly or indirectly, 100 percent of the capital stock (exclusive of directors' qualifying shares) of a corporation organized under the laws of a contiguous foreign country and maintained solely for the purpose of complying with the laws of such country as to title and operation of property, such foreign corporation may, at the option of the domestic corporation, be treated for the purpose of this subtitle as a domestic corporation."],[0,"(e) Includible tax-exempt organizations"],[0,"Despite the provisions of paragraph (1) of subsection (b), two or more organizations exempt from taxation under section 501, one or more of which is described in section 501(c)(2) and the others of which derive income from such 501(c)(2) organizations, shall be considered as includible corporations for the purpose of the application of subsection (a) to such organizations alone."],[0,"(f) Special rule for certain amounts derived from a corporation previously treated as a DISC"],[0,"In determining the consolidated taxable income of an affiliated group for any taxable year beginning after December 31, 1984, a corporation which had been a DISC and which would otherwise be a member of such group shall not be treated as such a member with respect to—"],[1,"(1) any distribution (or deemed distribution) of accumulated DISC income which was not treated as previously taxed income under section 805(b)(2)(A) of the Tax Reform Act of 1984, and"],[1,"(2) any amount treated as received under section 805(b)(3) of such Act."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/1504?type=usc&year=mostrecent&link-type=html"},"head":"§1504. Definitions","tname":"Internal Revenue Code","by":{"0":"51, 4, 4","1":"14, 14"}},{"t":"usc","label":"26 U.S.C. § 1552","url":"https://www.law.cornell.edu/uscode/text/26/1552","subs":["(a)"],"by":{"0":"47"}},{"t":"usc","label":"26 U.S.C. § 6401","url":"https://www.law.cornell.edu/uscode/text/26/6401","by":{"0":"32"}},{"t":"usc","label":"26 U.S.C. § 6402","url":"https://www.law.cornell.edu/uscode/text/26/6402","subs":["(a)","(k)","(2019)"],"stext":{"head":"§6402. Authority to make credits or refunds","paras":[[0,"(a) General rule"],[0,"In the case of any overpayment, the Secretary, within the applicable period of limitations, may credit the amount of such overpayment, including any interest allowed thereon, against any liability in respect of an internal revenue tax on the part of the person who made the overpayment and shall, subject to subsections (c), (d), (e), and (f), refund any balance to such person."],[0,"(b) Credits against estimated tax"],[0,"The Secretary is authorized to prescribe regulations providing for the crediting against the estimated income tax for any taxable year of the amount determined by the taxpayer or the Secretary to be an overpayment of the income tax for a preceding taxable year."],[0,"(c) Offset of past-due support against overpayments"],[0,"The amount of any overpayment to be refunded to the person making the overpayment shall be reduced by the amount of any past-due support (as defined in section 464(c) of the Social Security Act) owed by that person of which the Secretary has been notified by a State in accordance with section 464 of such Act. The Secretary shall remit the amount by which the overpayment is so reduced to the State collecting such support and notify the person making the overpayment that so much of the overpayment as was necessary to satisfy his obligation for past-due support has been paid to the State. The Secretary shall apply a reduction under this subsection first to an amount certified by the State as past due support under section 464 of the Social Security Act before any other reductions allowed by law. This subsection shall be applied to an overpayment prior to its being credited to a person's future liability for an internal revenue tax. For purposes of this subsection, any reference to a State shall include a reference to any Indian tribe or tribal organization receiving a grant under section 455(f) of the Social Security Act."],[0,"(d) Collection of debts owed to Federal agencies"],[0,"(1) In general"],[1,"Upon receiving notice from any Federal agency that a named person owes a past-due legally enforceable debt (other than past-due support subject to the provisions of subsection (c)) to such agency, the Secretary shall—"],[2,"(A) reduce the amount of any overpayment payable to such person by the amount of such debt;"],[2,"(B) pay the amount by which such overpayment is reduced under subparagraph (A) to such agency; and"],[2,"(C) notify the person making such overpayment that such overpayment has been reduced by an amount necessary to satisfy such debt."],[0,"(2) Priorities for offset"],[1,"Any overpayment by a person shall be reduced pursuant to this subsection after such overpayment is reduced pursuant to subsection (c) with respect to past-due support collected pursuant to an assignment under section 408(a)(3) of the Social Security Act (42 U.S.C. 608(a)(3)) and before such overpayment is reduced pursuant to subsections (e) and (f) and before such overpayment is credited to the future liability for tax of such person pursuant to subsection (b). If the Secretary receives notice from a Federal agency or agencies of more than one debt subject to paragraph (1) that is owed by a person to such agency or agencies, any overpayment by such person shall be applied against such debts in the order in which such debts accrued."],[0,"(3) Treatment of OASDI overpayments"],[0,"(A) Requirements"],[2,"Paragraph (1) shall apply with respect to an OASDI overpayment only if the requirements of paragraphs (1) and (2) of section 3720A(f) of title 31, United States Code, are met with respect to such overpayment."],[0,"(B) Notice; protection of other persons filing joint return"],[0,"(i) Notice"],[3,"In the case of a debt consisting of an OASDI overpayment, if the Secretary determines upon receipt of the notice referred to in paragraph (1) that the refund from which the reduction described in paragraph (1)(A) would be made is based upon a joint return, the Secretary shall—"],[4,"(I) notify each taxpayer filing such joint return that the reduction is being made from a refund based upon such return, and"],[4,"(II) include in such notification a description of the procedures to be followed, in the case of a joint return, to protect the share of the refund which may be payable to another person."],[0,"(ii) Adjustments based on protections given to other taxpayers on joint return"],[3,"If the other person filing a joint return with the person owing the OASDI overpayment takes appropriate action to secure his or her proper share of the refund subject to reduction under this subsection, the Secretary shall pay such share to such other person. The Secretary shall deduct the amount of such payment from amounts which are derived from subsequent reductions in refunds under this subsection and are payable to a trust fund referred to in subparagraph (C)."],[0,"(C) Deposit of amount of reduction into appropriate trust fund"],[2,"In lieu of payment, pursuant to paragraph (1)(B), of the amount of any reduction under this subsection to the Commissioner of Social Security, the Secretary shall deposit such amount in the Federal Old-Age and Survivors Insurance Trust Fund or the Federal Disability Insurance Trust Fund, whichever is certified to the Secretary as appropriate by the Commissioner of Social Security."],[0,"(D) OASDI overpayment"],[2,"For purposes of this paragraph, the term \"OASDI overpayment\" means any overpayment of benefits made to an individual under title II of the Social Security Act."],[0,"(e) Collection of past-due, legally enforceable State income tax obligations"],[0,"(1) In general"],[1,"Upon receiving notice from any State that a named person owes a past-due, legally enforceable State income tax obligation to such State, the Secretary shall, under such conditions as may be prescribed by the Secretary—"],[2,"(A) reduce the amount of any overpayment payable to such person by the amount of such State income tax obligation;"],[2,"(B) pay the amount by which such overpayment is reduced under subparagraph (A) to such State and notify such State of such person's name, taxpayer identification number, address, and the amount collected; and"],[2,"(C) notify the person making such overpayment that the overpayment has been reduced by an amount necessary to satisfy a past-due, legally enforceable State income tax obligation."],[1,"If an offset is made pursuant to a joint return, the notice under subparagraph (B) shall include the names, taxpayer identification numbers, and addresses of each person filing such return."],[0,"(2) Offset permitted only against residents of State seeking offset"],[1,"Paragraph (1) shall apply to an overpayment by any person for a taxable year only if the address shown on the Federal return for such taxable year of the overpayment is an address within the State seeking the offset."],[0,"(3) Priorities for offset"],[1,"Any overpayment by a person shall be reduced pursuant to this subsection—"],[2,"(A) after such overpayment is reduced pursuant to—"],[3,"(i) subsection (a) with respect to any liability for any internal revenue tax on the part of the person who made the overpayment;"],[3,"(ii) subsection (c) with respect to past-due support; and"],[3,"(iii) subsection (d) with respect to any past-due, legally enforceable debt owed to a Federal agency; and"],[2,"(B) before such overpayment is credited to the future liability for any Federal internal revenue tax of such person pursuant to subsection (b)."],[1,"If the Secretary receives notice from one or more agencies of the State of more than one debt subject to paragraph (1) or subsection (f) that is owed by such person to such an agency, any overpayment by such person shall be applied against such debts in the order in which such debts accrued."],[0,"(4) Notice; consideration of evidence"],[1,"No State may take action under this subsection until such State—"],[2,"(A) notifies by certified mail with return receipt the person owing the past-due State income tax liability that the State proposes to take action pursuant to this section;"],[2,"(B) gives such person at least 60 days to present evidence that all or part of such liability is not past-due or not legally enforceable;"],[2,"(C) considers any evidence presented by such person and determines that an amount of such debt is past-due and legally enforceable; and"],[2,"(D) satisfies such other conditions as the Secretary may prescribe to ensure that the determination made under subparagraph (C) is valid and that the State has made reasonable efforts to obtain payment of such State income tax obligation."],[0,"(5) Past-due, legally enforceable State income tax obligation"],[1,"For purposes of this subsection, the term \"past-due, legally enforceable State income tax obligation\" means a debt—"],[2,"(A)(i) which resulted from—"],[3,"(I) a judgment rendered by a court of competent jurisdiction which has determined an amount of State income tax to be due; or"],[3,"(II) a determination after an administrative hearing which has determined an amount of State income tax to be due; and"],[2,"(ii) which is no longer subject to judicial review; or"],[2,"(B) which resulted from a State income tax which has been assessed but not collected, the time for redetermination of which has expired, and which has not been delinquent for more than 10 years."],[1,"For purposes of this paragraph, the term \"State income tax\" includes any local income tax administered by the chief tax administration agency of the State."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/6402?type=usc&year=mostrecent&link-type=html"},"head":"§6402. Authority to make credits or refunds","tname":"Internal Revenue Code","by":{"0":"48, passim","1":"14, 14"}},{"t":"usc","label":"26 U.S.C. § 6611","url":"https://www.law.cornell.edu/uscode/text/26/6611","subs":["(f)"],"by":{"0":"43, 42, 48"}},{"t":"usc","label":"28 U.S.C. § 158","url":"https://www.law.cornell.edu/uscode/text/28/158","subs":["(a)"],"stext":{"head":"§158. Appeals","paras":[[0,"(a) The district courts of the United States shall have jurisdiction to hear appeals 1"],[1,"(1) from final judgments, orders, and decrees;"],[1,"(2) from interlocutory orders and decrees issued under section 1121(d) of title 11 increasing or reducing the time periods referred to in section 1121 of such title; and"],[1,"(3) with leave of the court, from other interlocutory orders and decrees;"],[0,"of bankruptcy judges entered in cases and proceedings referred to the bankruptcy judges under section 157 of this title. An appeal under this subsection shall be taken only to the district court for the judicial district in which the bankruptcy judge is serving."],[0,"(b)(1) The judicial council of a circuit shall establish a bankruptcy appellate panel service composed of bankruptcy judges of the districts in the circuit who are appointed by the judicial council in accordance with paragraph (3), to hear and determine, with the consent of all the parties, appeals under subsection (a) unless the judicial council finds that—"],[1,"(A) there are insufficient judicial resources available in the circuit; or"],[1,"(B) establishment of such service would result in undue delay or increased cost to parties in cases under title 11."],[0,"Not later than 90 days after making the finding, the judicial council shall submit to the Judicial Conference of the United States a report containing the factual basis of such finding."],[0,"(2)(A) A judicial council may reconsider, at any time, the finding described in paragraph (1)."],[0,"(B) On the request of a majority of the district judges in a circuit for which a bankruptcy appellate panel service is established under paragraph (1), made after the expiration of the 1-year period beginning on the date such service is established, the judicial council of the circuit shall determine whether a circumstance specified in subparagraph (A) or (B) of such paragraph exists."],[0,"(C) On its own motion, after the expiration of the 3-year period beginning on the date a bankruptcy appellate panel service is established under paragraph (1), the judicial council of the circuit may determine whether a circumstance specified in subparagraph (A) or (B) of such paragraph exists."],[0,"(D) If the judicial council finds that either of such circumstances exists, the judicial council may provide for the completion of the appeals then pending before such service and the orderly termination of such service."],[0,"(3) Bankruptcy judges appointed under paragraph (1) shall be appointed and may be reappointed under such paragraph."],[0,"(4) If authorized by the Judicial Conference of the United States, the judicial councils of 2 or more circuits may establish a joint bankruptcy appellate panel comprised of bankruptcy judges from the districts within the circuits for which such panel is established, to hear and determine, upon the consent of all the parties, appeals under subsection (a) of this section."],[0,"(5) An appeal to be heard under this subsection shall be heard by a panel of 3 members of the bankruptcy appellate panel service, except that a member of such service may not hear an appeal originating in the district for which such member is appointed or designated under section 152 of this title."],[0,"(6) Appeals may not be heard under this subsection by a panel of the bankruptcy appellate panel service unless the district judges for the district in which the appeals occur, by majority vote, have authorized such service to hear and determine appeals originating in such district."],[0,"(c)(1) Subject to subsections (b) and (d)(2), each appeal under subsection (a) shall be heard by a 3-judge panel of the bankruptcy appellate panel service established under subsection (b)(1) unless—"],[1,"(A) the appellant elects at the time of filing the appeal; or"],[1,"(B) any other party elects, not later than 30 days after service of notice of the appeal;"],[0,"to have such appeal heard by the district court."],[0,"(2) An appeal under subsections (a) and (b) of this section shall be taken in the same manner as appeals in civil proceedings generally are taken to the courts of appeals from the district courts and in the time provided by Rule 8002 of the Bankruptcy Rules."],[0,"(d)(1) The courts of appeals shall have jurisdiction of appeals from all final decisions, judgments, orders, and decrees entered under subsections (a) and (b) of this section."],[0,"(2)(A) The appropriate court of appeals shall have jurisdiction of appeals described in the first sentence of subsection (a) if the bankruptcy court, the district court, or the bankruptcy appellate panel involved, acting on its own motion or on the request of a party to the judgment, order, or decree described in such first sentence, or all the appellants and appellees (if any) acting jointly, certify that—"],[1,"(i) the judgment, order, or decree involves a question of law as to which there is no controlling decision of the court of appeals for the circuit or of the Supreme Court of the United States, or involves a matter of public importance;"],[1,"(ii) the judgment, order, or decree involves a question of law requiring resolution of conflicting decisions; or"],[1,"(iii) an immediate appeal from the judgment, order, or decree may materially advance the progress of the case or proceeding in which the appeal is taken;"],[0,"and if the court of appeals authorizes the direct appeal of the judgment, order, or decree."],[0,"(B) If the bankruptcy court, the district court, or the bankruptcy appellate panel—"],[1,"(i) on its own motion or on the request of a party, determines that a circumstance specified in clause (i), (ii), or (iii) of subparagraph (A) exists; or"],[1,"(ii) receives a request made by a majority of the appellants and a majority of appellees (if any) to make the certification described in subparagraph (A);"],[0,"then the bankruptcy court, the district court, or the bankruptcy appellate panel shall make the certification described in subparagraph (A)."],[0,"(C) The parties may supplement the certification with a short statement of the basis for the certification."],[0,"(D) An appeal under this paragraph does not stay any proceeding of the bankruptcy court, the district court, or the bankruptcy appellate panel from which the appeal is taken, unless the respective bankruptcy court, district court, or bankruptcy appellate panel, or the court of appeals in which the appeal is pending, issues a stay of such proceeding pending the appeal."],[0,"(E) Any request under subparagraph (B) for certification shall be made not later than 60 days after the entry of the judgment, order, or decree."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/158?type=usc&year=mostrecent&link-type=html"},"head":"§158. Appeals","tname":"Judiciary and Judicial Procedure","by":{"0":"16","1":"14"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"4"}},{"t":"reg","label":"26 C.F.R. § 1.1502-0","url":"https://www.ecfr.gov/current/title-26/section-1.1502-0","by":{"0":"5"}},{"t":"reg","label":"26 C.F.R. § 1.1502-2","url":"https://www.ecfr.gov/current/title-26/section-1.1502-2","by":{"0":"1, 47"}},{"t":"reg","label":"26 C.F.R. § 1.1502-6","url":"https://www.ecfr.gov/current/title-26/section-1.1502-6","subs":["(a)","(b)"],"by":{"0":"1, 8, 9, 47, 41"}},{"t":"reg","label":"26 C.F.R. § 1.1502-11","url":"https://www.ecfr.gov/current/title-26/section-1.1502-11","subs":["(a)","(a)(2)"],"by":{"0":"1, 45, 6, 7, 43, 7"}},{"t":"reg","label":"26 C.F.R. § 1.1502-12","url":"https://www.ecfr.gov/current/title-26/section-1.1502-12","subs":["(a)","(j)"],"by":{"0":"1, 7, 44, 49, 7"}},{"t":"reg","label":"26 C.F.R. § 1.1502-13","url":"https://www.ecfr.gov/current/title-26/section-1.1502-13","subs":["(a)(2)","(c)(1)","(c)(7)(ii)"],"by":{"0":"1, 49, 6, 50, 7"}},{"t":"reg","label":"26 C.F.R. § 1.1502-21","url":"https://www.ecfr.gov/current/title-26/section-1.1502-21","subs":["(b)","(b)(2)(iv)","(e)","(f)"],"by":{"0":"44, 46, 43, 43"}},{"t":"reg","label":"26 C.F.R. § 1.1502-77","url":"https://www.ecfr.gov/current/title-26/section-1.1502-77","subs":["(a)","(a)(1)","(c)(1)","(d)","(d)(1)","(d)(5)"],"by":{"0":"8, 41, 8, 14, 55, 8, 42, 8, 14, 8, passim, 8, 8, 8","2":"14, 15, 14"}},{"t":"reg","label":"26 C.F.R. § 1.1502-78","url":"https://www.ecfr.gov/current/title-26/section-1.1502-78","subs":["(a)","(b)(1)"],"by":{"0":"passim, 21, 33, 41"}},{"t":"reg","label":"26 C.F.R. § 1.1502-79","url":"https://www.ecfr.gov/current/title-26/section-1.1502-79","subs":["(a)(3)"],"by":{"0":"44"}},{"t":"reg","label":"26 C.F.R. § 1.1552-1","url":"https://www.ecfr.gov/current/title-26/section-1.1552-1","by":{"0":"47"}},{"t":"reg","label":"26 C.F.R. § 301.6402-7","url":"https://www.ecfr.gov/current/title-26/section-301.6402-7","subs":["(a)(1)","(c)","(d)","(e)","(g)(2)(iii)","(j)"],"by":{"0":"20, 21, 33, 41, 33, 33, 33, 46, 41"}},{"t":"reg","label":"Addendum to the Interagency Policy Statement on Income Tax Allocation in a Holding Company Structure, 79 Fed. Reg. 35,228","url":"https://www.govinfo.gov/link/fr/79/35228","by":{"0":"38","1":"9, 47"}},{"t":"reg","label":"Guidance Under Section 1502; Application of Section 108 to Members of a Consolidated Group, 68 Fed. Reg. 52,487","url":"https://www.govinfo.gov/link/fr/68/52487","by":{"0":"46"}},{"t":"reg","label":"Interagency Policy Statement on Income Tax Allocation in a Holding Company Structure, 63 Fed. Reg. 64,757","url":"https://www.govinfo.gov/link/fr/63/64757","by":{"0":"37, 38","1":"8, 9, 11, 30, 42, 47","2":"21"}},{"t":"case","label":"Argus Real Estate, Inc. v. E-470 Pub. Highway Auth.","cite":"97 P.3d 215","y":2003,"court":"Colo. App.","url":"https://www.courtlistener.com/c/P.3d/97/215/","sum":"Finding that an agency relationship had been created by a contract stating that the parties “entered into an agreement for [A] to serve as agent to collect” money owed to P.","sumSrc":"brief:1","by":{"1":"45","2":"18"}},{"t":"case","label":"Begier v. IRS","cite":"496 U.S. 53","y":1990,"id":"1989/89-393","sc":1,"sum":"AIA's trust-fund tax payments from its general accounts were transfers of property held in trust and therefore cannot be avoided as preferences.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"2"}},{"t":"case","label":"Burlington Indus., Inc. v. Eller th","cite":"524 U.S. 742","y":1998,"id":"1997/97-569","sc":1,"sum":"In a 7-to-2 opinion, the Court held that employers are vicariously liable for supervisors who create hostile working conditions for those over whom they have authority.","sumSrc":"Oyez","by":{"1":"18, 22, 33, 36"}},{"t":"case","label":"Cantor v. FDIC (In re Downey Fin. Corp.)","cite":"593 Fed. Appx. 123","y":2015,"court":"3d Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./593/123/","by":{"1":"7"}},{"t":"case","label":"Community for Creative Non-Violence v. Reid","cite":"490 U.S. 730","y":1989,"id":"1988/88-293","sc":1,"sum":"The Court held that the statue's preparation was not a \"work for hire\" as defined by the Act because Reid was not a CCNV employee. Instead, CCNV hired Reid as an independent contractor.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Exxon Co. v. Sofec, Inc.","cite":"517 U.S. 830","y":1996,"id":"1995/95-129","sc":1,"sum":"The Court held that a plaintiff in admiralty that is the superseding cause of its own injury, and thus the sole, proximate cause, cannot recover part of its damages from tort-feasors or contracting partners whose blameworthy actions were causes in fact of the injury.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"FDIC v. Zucker (In re NetBank, Inc.)","cite":"729 F.3d 1344","y":2013,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/729/1344/","by":{"1":"6, 42"}},{"t":"case","label":"Graver Tank & Mfg. Co. v. Linde Air Prods. Co.","cite":"336 U.S. 271","y":1949,"id":"scdb/1948-044","sc":1,"sum":"1. Certain flux claims of Jones patent No. 2,043,960, for an electric welding process and for fluxes, or compositions, to be used therewith, held valid and infringed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"Green v. Brennan","cite":"136 S. Ct. 1769","y":2016,"id":"2015/14-613","sc":1,"sum":"The Court held that the 45-day period in which an employee must file a constructive discharge claim under federal employment discrimination law begins to run on the date the employee resigns.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Helvering v. Morgan’s, Inc.","cite":"293 U.S. 121","y":1934,"id":"scdb/1934-001","sc":1,"by":{"1":"3, 30"}},{"t":"case","label":"Jump v. Manchester Life & Cas. Mgmt. Corp.","cite":"579 F.2d 449","y":1978,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/579/449/","by":{"1":"7, 35"}},{"t":"case","label":"Lebron v. National R.R. Passenger Corp.","cite":"513 U.S. 374","y":1995,"id":"1994/93-1525","sc":1,"sum":"Where, as here, the Government creates a corporation by special law, for the furtherance of governmental objectives, and retains for itself permanent authority to appoint a majority of that corporation's directors, the corporation is part of the Government for purposes of the First Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"48"}},{"t":"case","label":"Nationwide Mut. Ins. Co. v. Darden","cite":"503 U.S. 318","y":1992,"id":"1991/90-1802","sc":1,"sum":"Contracts between petitioners Nationwide Mutual Insurance Co. et al. and respondent Darden provided, among other things, that Darden would sell only Nationwide policies, that Nationwide would enroll him in a company retirement plan for agents, and that he would forfeit his entitlement to plan benefits if, within a year of his termination and 25 miles of his prior business location, he sold insurance for Nationwide's …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"32"}},{"t":"case","label":"Official Comm. of Unsecured Creditors & Cold Spring Shipping, L.P. v. PSS Steamship Co. (In re Prudential Lines Inc.)","cite":"928 F.2d 565","y":1991,"url":"https://www.courtlistener.com/c/F.2d/928/565/","by":{"1":"7"}},{"t":"case","label":"Pinnacol Assurance v. Hoff","cite":"375 P.3d 1214","y":2016,"court":"Colo.","url":"https://www.courtlistener.com/c/P.3d/375/1214/","by":{"1":"16"}},{"t":"case","label":"Preiser v. Newkirk","cite":"422 U.S. 395","y":1975,"id":"1974/74-107","sc":1,"sum":"In light of respondent's return to the medium security prison and later transfer to a minimum security prison, the suit does not present a case or controversy as required by Art. III of the Constitution but is now moot and must be dismissed, since as to the original complaint there is now no reasonable expectation that the wrong will be repeated and the question presented does not fall within the category of harm …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"School Dist. No. 1 in the Cnty. of Denver v. Denver Classroom Teachers Ass’n","cite":"433 P.3d 38","y":2019,"court":"Colo.","url":"https://www.courtlistener.com/c/P.3d/433/38/","sum":"Explaining that in Colorado, the “primary goal” of contract interpretation “is to discern and effectuate the * * * intent” of the contracting parties.","sumSrc":"brief:1","by":{"1":"47"}},{"t":"case","label":"Sekhar v. United States","cite":"570 U.S. 729","y":2013,"id":"2012/12-357","sc":1,"sum":"The Court held that attempting to compel a person to issue a recommendation does not constitute extortion under the Hobbs Act.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"US Airways, Inc. v. McCutchen","cite":"569 U.S. 88","y":2013,"id":"2012/11-1285","sc":1,"sum":"The Court held that when a contract is silent on allocation of relief, the parties' intentions are best determined by the common-fund doctrine.","sumSrc":"Oyez","by":{"1":"27, 42"}},{"t":"case","label":"United States v. Munsey Trust Co.","cite":"332 U.S. 234","y":1947,"id":"scdb/1946-135","sc":1,"sum":"1. N'otwithstanding claims of a surety on a statutory payment bond (given under 40 U. S. C. § 270a) for reimbursement for sums paid to laborers and materialmen, the Government may set off, against unappropriated percentages of progress payments withheld by it and due to the contractor on the construction contract, a debt owed to it by the contractor as a result of a separate and independent transaction.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"7"}},{"t":"case","label":"Western Dealer Mgmt., Inc. v. England (In re Bob Richards Chrysler-Plymouth Corp.)","cite":"473 F.2d 262","y":1973,"url":"https://www.courtlistener.com/c/F.2d/473/262/","op":3,"by":{"1":"passim"}},{"t":"case","label":"Zucker v. FDIC (In re BankUnited Fin. Corp.)","cite":"727 F.3d 1100","y":2013,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/727/1100/","sum":"Stating that the court “cannot imagine” why an affiliated group would create a debtorcreditor relationship for a tax refund allocated to one subsidiary.","sumSrc":"brief:1","by":{"1":"7, 43"}},{"t":"usc","label":"11 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/11/101","by":{"1":"2, 12"}},{"t":"usc","label":"11 U.S.C. § 501","url":"https://www.law.cornell.edu/uscode/text/11/501","by":{"1":"2, 12"}},{"t":"usc","label":"11 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/11/701","by":{"1":"2, 12"}},{"t":"usc","label":"11 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/11/1101","by":{"1":"2, 12"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","by":{"1":"33"}},{"t":"usc","label":"12 U.S.C. § 1811","url":"https://www.law.cornell.edu/uscode/text/12/1811","by":{"1":"12"}},{"t":"usc","label":"12 U.S.C. § 1813","url":"https://www.law.cornell.edu/uscode/text/12/1813","by":{"1":"12"}},{"t":"usc","label":"26 U.S.C. § 1503","url":"https://www.law.cornell.edu/uscode/text/26/1503","by":{"1":"2"}},{"t":"case","label":"Boyer v. Karakehian","cite":"915 P.2d 1295","y":1996,"court":"Colo.","url":"https://www.courtlistener.com/c/P.2d/915/1295/","by":{"2":"21"}},{"t":"case","label":"Corrales v. Days Inn Worldwide, Inc.","cite":"2005 WL 4655135","y":2005,"court":"Colo. D. Ct. Dec. 5","by":{"2":"18"}},{"t":"case","label":"Grupo Mexicano de Desarrollo, S.A. v. All. Bond Fund, Inc.","cite":"527 U.S. 308","y":1999,"id":"1998/98-231","sc":1,"sum":"The Court held that the District Court lacked the authority to issue a preliminary injunction preventing defendants being sued by creditors from disposing of their assets pending adjudication of the creditor's contract claim for monetary damages because such a remedy was historically unavailable from a court of equity.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"Lubin v. FDIC","cite":"2011 WL 825751","y":2011,"court":"N.D. Ga. Mar. 2","by":{"2":"10"}},{"t":"case","label":"Luis v. United States","cite":"136 S. Ct. 1083","y":2016,"id":"2015/14-419","sc":1,"sum":"The Court determined that the pretrial restraining of a defendant's assets untainted by their crime that are needed to retain counsel of choice violates the Sixth Amendment.","sumSrc":"Oyez","by":{"2":"4, 6, 13"}},{"t":"case","label":"Mastrobuono v. Shearson Lehman Hutton, Inc.","cite":"514 U.S. 52","y":1995,"id":"1994/94-18","sc":1,"sum":"The arbitral award should have been enforced as within the scope of the contract between the parties.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"15"}},{"t":"case","label":"Moses v. Diocese of Colo.","cite":"863 P.2d 310","y":1993,"court":"Colo.","url":"https://www.courtlistener.com/c/P.2d/863/310/","ar":1,"by":{"2":"16, 18, 20"}},{"t":"case","label":"Town of Castle Rock v. Gonzales","cite":"545 U.S. 748","y":2005,"id":"2004/04-278","sc":1,"sum":"The Court ruled that Gonzales had no constitutionally-protected property interest in the enforcement of the restraining order, and therefore could not claim that the police had violated her right to due process.","sumSrc":"Oyez","by":{"2":"15"}}]};